import { randomUUID } from 'node:crypto';
import { AppHostError, requireCondition } from '../errors.js';
import { loopbackOrigin } from '../descriptor.js';

export const LIBRARY_ROUTES=['/hanamesh/library','/hanamesh/library/sources','/hanamesh/library/install','/hanamesh/library/provision','/hanamesh/library/uninstall','/hanamesh/library/events'];
async function jsonBody(req){const chunks=[];let total=0;for await(const chunk of req){total+=chunk.length;requireCondition(total<=65_536,'BODY_TOO_LARGE','Request body is too large.',{},413);chunks.push(chunk);}try{return JSON.parse(Buffer.concat(chunks).toString('utf8'));}catch{throw new AppHostError('INVALID_JSON','Malformed JSON.',{},400);}}
function send(res,status,value){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','content-security-policy':"default-src 'none'; frame-ancestors 'none'"});res.end(JSON.stringify(value));}
export function createLibraryHttpHandler(library,{parentOrigin,authenticate,authorize}){parentOrigin=loopbackOrigin(parentOrigin);return async(req,res)=>{const traceId=randomUUID();try{
  requireCondition(req.headers.host===new URL(parentOrigin).host,'HOST_DENIED','Unrecognized request host.',{},403);const url=new URL(req.url,parentOrigin),path=url.pathname;requireCondition(LIBRARY_ROUTES.includes(path),'NOT_FOUND','Unknown library route.',{},404);
  const readOnly=req.method==='GET'&&['/hanamesh/library','/hanamesh/library/sources','/hanamesh/library/events'].includes(path);requireCondition(readOnly||req.method==='POST','METHOD_NOT_ALLOWED','Unsupported library method.',{},405);
  requireCondition(!req.headers.origin||req.headers.origin===parentOrigin,'ORIGIN_DENIED','Unapproved browser origin.',{},403);requireCondition(req.headers['sec-fetch-dest']!=='iframe','FRAME_CONTROL_DENIED','An application frame cannot control the host.',{},403);
  if(!readOnly)requireCondition(req.headers.origin===parentOrigin&&req.headers['x-hanamesh-client']==='workspace-v1','CSRF_DENIED','Workspace origin and explicit client header are required.',{},403);
  const subject=await authenticate(req);requireCondition(subject&&typeof subject.principalId==='string','UNAUTHENTICATED','Host authentication is required.',{},401);const input=readOnly?Object.fromEntries(url.searchParams):await jsonBody(req);requireCondition(await authorize(subject,path,input)===true,'FORBIDDEN','Operation is not authorized.',{},403);
  let result;if(path==='/hanamesh/library'&&readOnly)result=await library.list();else if(path==='/hanamesh/library/sources'&&readOnly)result=library.sources();else if(path==='/hanamesh/library/sources')result=await library.replaceSources(input);else if(path==='/hanamesh/library/install')result=await library.install(input);else if(path==='/hanamesh/library/provision')result=await library.provision(input);else if(path==='/hanamesh/library/uninstall')result=await library.uninstall(input);else{requireCondition(Object.keys(input).every(key=>key==='after'),'UNKNOWN_FIELDS','Unknown event parameters.');result=library.events(Number(input.after??0));}
  send(res,path.includes('/install')||path.includes('/provision')||path.includes('/uninstall')?202:200,{...result,traceId});
}catch(error){const trusted=error instanceof AppHostError;send(res,trusted?error.status:500,{error:{code:trusted?error.code:'INTERNAL_ERROR',message:trusted?error.message:'The operation could not be completed.',...(trusted?{details:error.details}:{})},traceId});}};}
